insert into schools (id, name, name_ko, usnews_rank, tier, sat_mid50_low, sat_mid50_high, gpa_note, intl_accept_rate, need_blind_intl, demonstrated_interest, direct_admit_majors, what_they_value, source_url, test_policy, intro_ko, location_note) values (1, 'Princeton University', '프린스턴 대학교', 1, 1, 1490, 1560, '신입생 72%가 고교 GPA 4.0 (CDS 2025-26 C11)', null, true, false, '{}', '최신 CDS(2025-26) C7에서 교과 난이도(rigor), 석차, GPA, 표준화 시험 점수, 에세이, 추천서, 특별활동, 재능, 인성·개인 자질을 모두 Very Important로 공식 표시한다. 입학처 공식 페이지는 ''지적 호기심을 갖고 학업적 우수성을 추구해 온 학생''과 ''학교와 커뮤니티에서 변화를 만들어내는 학생''을 찾는다고 밝히고 있다.', 'https://ir.princeton.edu/document/606', 'test-optional', '미국 뉴저지주 프린스턴(Princeton, NJ)에 위치한 사립 종합대학으로, 교외(suburban) 주거형 단일 캠퍼스다.', '뉴욕과 필라델피아 사이의 소도시 대학 타운에 있으며, 두 대도시까지 기차로 약 1시간 거리이고 사계절이 뚜렷한 미국 북동부 기후다.');
insert into schools (id, name, name_ko, usnews_rank, tier, sat_mid50_low, sat_mid50_high, gpa_note, intl_accept_rate, need_blind_intl, demonstrated_interest, direct_admit_majors, what_they_value, source_url, test_policy, intro_ko, location_note) values (2, 'Massachusetts Institute of Technology', '매사추세츠 공과대학교 (MIT)', 2, 1, 1520, 1570, 'GPA 분포는 미공개(N/Av), 고교 석차 상위 10% 이내 신입생 97% (CDS 2025-26 C10)', 1.96, true, false, '{}', '입학처 공식 ''What we look for'' 페이지에서 MIT 미션(과학기술로 세상을 더 낫게)과의 정합성, 협업 정신, 주도성, 실패를 두려워하지 않는 도전, 손으로 직접 만드는 창의성, 소수의 관심사에 대한 진정한 몰입과 호기심, 삶의 균형을 명시한다. CDS 2025-26 C7에서 Very Important로 표시된 유일한 항목은 인성·개인 자질(character/personal qualities)이다.', 'https://ir.mit.edu/projects/2025-26-common-data-set/', 'test-required', '미국 매사추세츠주 케임브리지(Cambridge, MA)의 찰스강변에 위치한 사립 공과 중심 대학으로, 도시(urban) 캠퍼스다.', '보스턴 대도시권에 속해 찰스강 건너편이 보스턴 시내이며, 겨울이 춥고 눈이 잦은 미국 북동부 기후다.');
insert into schools (id, name, name_ko, usnews_rank, tier, sat_mid50_low, sat_mid50_high, gpa_note, intl_accept_rate, need_blind_intl, demonstrated_interest, direct_admit_majors, what_they_value, source_url, test_policy, intro_ko, location_note) values (3, 'Harvard University', '하버드 대학교', 3, 1, null, null, '신입생 74.7%가 고교 GPA 4.0 (CDS 2025-26 C11)', null, true, false, '{}', '입학처 공식 ''What We Look For'' 페이지에서 성장과 잠재력(자기 역량을 최대로 발휘해 왔는가), 관심사와 활동(무엇을 했고 무엇을 배웠는가), 인성(같이 지내고 싶은 사람인가), 하버드 커뮤니티에 대한 기여 가능성을 심사 기준으로 명시한다. 참고로 CDS 2025-26 C7에서는 어떤 요소도 Very Important로 표시하지 않고 대부분 Considered로만 표시한다.', 'https://oira.harvard.edu/files/2026/07/CDS_2025-2026.pdf', 'test-required', '미국 매사추세츠주 케임브리지(Cambridge, MA)에 위치한 사립 종합대학으로, 도시(urban) 캠퍼스다.', '보스턴 대도시권의 대학 도시 케임브리지에 있으며, 겨울이 춥고 눈이 잦은 미국 북동부 기후다.');
insert into schools (id, name, name_ko, usnews_rank, tier, sat_mid50_low, sat_mid50_high, gpa_note, intl_accept_rate, need_blind_intl, demonstrated_interest, direct_admit_majors, what_they_value, source_url, test_policy, intro_ko, location_note) values (4, 'Stanford University', '스탠퍼드 대학교', 4, 1, 1520, 1570, '신입생 73%가 고교 GPA 4.0 (CDS 2025-26 C11, 평균 GPA 3.94/4.0 unweighted)', null, false, false, '{}', '최신 CDS(2025-26) C7에서 교과 난이도, 석차, GPA, 표준화 시험 점수, 에세이, 추천서, 특별활동, 재능, 인성·개인 자질을 모두 Very Important로 공식 표시한다. 입학처 공식 FAQ는 학업적 탁월성과 함께 GPA·점수만으로는 드러나지 않는 지적 활력(intellectual vitality), 교내외 활동에서의 지속적 헌신과 리더십을 평가한다고 밝힌다.', 'https://irds.stanford.edu/data-findings/cds', 'test-required', '미국 캘리포니아주 스탠퍼드(Stanford, CA, 팰로앨토 인접)에 위치한 사립 종합대학으로, 넓은 교외(suburban)형 캠퍼스다.', '샌프란시스코 베이 에리어의 실리콘밸리 중심부에 있으며, 연중 온화하고 건조한 캘리포니아 기후다.');
insert into schools (id, name, name_ko, usnews_rank, tier, sat_mid50_low, sat_mid50_high, gpa_note, intl_accept_rate, need_blind_intl, demonstrated_interest, direct_admit_majors, what_they_value, source_url, test_policy, intro_ko, location_note) values (5, 'Yale University', '예일 대학교', 4, 1, 1480, 1560, 'GPA 분포는 미공개, 고교 석차 상위 10% 이내 신입생 97% (CDS 2025-26 C10)', null, true, false, '{}', '입학처 공식 ''What Yale Looks For'' 페이지는 ''예일의 자원을 가장 잘 활용할 사람''과 ''예일 커뮤니티에 가장 크게 기여할 사람''이라는 두 질문을 심사의 축으로 명시하고, 학업 잠재력(탐구심 있는 명민한 지성), 타인에 대한 배려와 공동선에 대한 관심, 자기 역량을 확장하려는 탐구 의지를 든다. CDS 2025-26 C7에서는 교과 난이도, 석차, GPA, 에세이, 추천서, 특별활동, 재능, 인성을 Very Important로 표시한다(표준화 시험은 Considered).', 'https://oir.yale.edu/sites/default/files/yale_cds_2025-26_md_20260616.pdf', 'test-required', '미국 코네티컷주 뉴헤이븐(New Haven, CT)에 위치한 사립 종합대학으로, 중소도시 도심(urban)에 자리한 주거형(기숙 칼리지) 캠퍼스다.', '뉴욕에서 기차로 약 2시간 거리의 항구 중소도시이며, 사계절이 뚜렷한 미국 북동부 기후다.');
insert into schools (id, name, name_ko, usnews_rank, tier, sat_mid50_low, sat_mid50_high, gpa_note, intl_accept_rate, need_blind_intl, demonstrated_interest, direct_admit_majors, what_they_value, source_url, test_policy, intro_ko, location_note) values (6, 'University of Chicago', '시카고대학교', 6, 1, null, null, null, null, null, null, '{}', '입학처 공식 지원 페이지는 ''학업·활동 기록, 에세이, 추천서, SAT/ACT 점수 등 어느 한 가지 요소만으로 합격 여부가 결정되지 않는다''고 명시하며, 지원자가 자신의 목소리로 자기 이야기를 보여줄 것을 강조합니다. 시험은 test-optional ''No Harm'' 정책으로, 점수는 유리하게 작용할 때만 심사에 반영된다고 공식 안내합니다.', 'https://collegeadmissions.uchicago.edu/apply/', 'test-optional', '일리노이주 시카고 남부 하이드파크(Hyde Park) 지역에 위치한 도시형 캠퍼스입니다.', '미국 3대 도시인 시카고 도심에서 남쪽으로 약 11km, 미시간 호수 인근에 있으며 겨울이 추운 편입니다.');
insert into schools (id, name, name_ko, usnews_rank, tier, sat_mid50_low, sat_mid50_high, gpa_note, intl_accept_rate, need_blind_intl, demonstrated_interest, direct_admit_majors, what_they_value, source_url, test_policy, intro_ko, location_note) values (7, 'Duke University', '듀크 대학교', 7, 1, 1510, 1570, null, null, false, true, '{"engineering"}', '공식 ''What We Look For'' 페이지에서 야망과 호기심, 재능과 끈기, 에너지와 인간미(ambition and curiosity, talent and persistence, energy and humanity)를 찾는다고 밝히며, 교과 난이도·성적·추천서·활동·에세이 5가지를 평가 요소로 명시한다. CDS 2025-26 C7 기준 Very Important는 교과 이수 난이도, GPA, 추천서, 특별활동, 재능/능력, 인성/개인 자질이다. (출처: admissions.duke.edu/what-we-look-for + CDS C7)', 'https://ir.provost.duke.edu/sites/default/files/CDS_PDF_2025-2026-20260622-website-published-version.pdf', 'test-optional', '노스캐롤라이나주 더럼의 교외형 캠퍼스를 가진 사립 종합대학이다.', '인구 약 28만의 중견 도시 더럼에 있으며, 리서치 트라이앵글 지역에 속하고 숲으로 둘러싸인 넓은 고딕 양식 캠퍼스다.');
insert into schools (id, name, name_ko, usnews_rank, tier, sat_mid50_low, sat_mid50_high, gpa_note, intl_accept_rate, need_blind_intl, demonstrated_interest, direct_admit_majors, what_they_value, source_url, test_policy, intro_ko, location_note) values (8, 'Johns Hopkins University', '존스 홉킨스 대학교', 7, 1, 1530, 1565, '신입생 66.1%가 GPA 4.0, 평균 GPA 3.93 (CDS 2025-26 C11·C12)', null, false, false, '{"engineering"}', '공식 FAQ에서 지원서 전반에 걸쳐 학업적 성격(academic character), 임팩트와 주도성(impact and initiative), 학교와의 전반적 적합성(overall match)을 본다고 명시한다. CDS 2025-26 C7 기준 Very Important는 교과 이수 난이도, 석차, GPA, 표준화 시험 점수, 에세이, 추천서다. (출처: apply.jhu.edu FAQ + CDS C7)', 'https://oira.jhu.edu/wp-content/uploads/2025-2026-CDS-Johns-Hopkins-University-v2.pdf', 'test-required', '메릴랜드주 볼티모어 북부 주거지역에 있는 사립 연구중심대학(학부는 Homewood 캠퍼스)이다.', '인구 약 57만의 대도시 볼티모어에 있으며, 도심에서 북쪽으로 떨어진 녹지형 캠퍼스이고 워싱턴 D.C.까지 차로 약 1시간 거리다.');
insert into schools (id, name, name_ko, usnews_rank, tier, sat_mid50_low, sat_mid50_high, gpa_note, intl_accept_rate, need_blind_intl, demonstrated_interest, direct_admit_majors, what_they_value, source_url, test_policy, intro_ko, location_note) values (9, 'Northwestern University', '노스웨스턴 대학교', 7, 1, 1510, 1560, null, null, false, true, '{"engineering","arts","social_sci"}', '공식 입학처는 접근성(college access)에 대한 약속과 결합된 전체론적 검토를 강조하며, 성적·교과 난이도·추천서·수상 실적·에세이를 지원자의 학교·환경 맥락 속에서 평가한다고 밝힌다. CDS 2024-25 C7 기준 Very Important는 교과 이수 난이도, 석차, GPA, 에세이, 추천서, 특별활동, 재능/능력, 인성/개인 자질이다. (출처: admissions.northwestern.edu + CDS C7)', 'https://enrollment.northwestern.edu/data/2024-2025.pdf', 'test-optional', '일리노이주 에번스턴의 미시간 호숫가에 캠퍼스를 둔 사립 종합대학이다.', '시카고 도심에서 북쪽으로 약 20km 떨어진 교외 도시 에번스턴(인구 약 7.5만)에 있으며, 호수에 면한 캠퍼스로 겨울이 춥고 바람이 강한 기후다.');
insert into schools (id, name, name_ko, usnews_rank, tier, sat_mid50_low, sat_mid50_high, gpa_note, intl_accept_rate, need_blind_intl, demonstrated_interest, direct_admit_majors, what_they_value, source_url, test_policy, intro_ko, location_note) values (10, 'University of Pennsylvania', '펜실베이니아 대학교(유펜)', 7, 1, 1510, 1560, '신입생 59%가 GPA 4.0, 평균 GPA 3.9 (CDS 2024-25 C11·C12)', null, false, false, '{"engineering","business"}', '공식 ''What Penn Looks For'' 페이지는 전인적 검토(whole-person review)를 통해 벤저민 프랭클린의 정신 — 개방적이고 호기심 많으며 창의적이고 실용적이며 분야를 넘나드는 연결 — 과 사회에 대한 기여(service to society)를 지향하는 학생을 찾는다고 밝힌다. CDS 2024-25 C7 기준 Very Important는 교과 이수 난이도, GPA, 에세이, 추천서, 인성/개인 자질이다. (출처: admissions.upenn.edu What Penn Looks For + CDS C7)', 'https://admissions.upenn.edu/how-to-apply/resources-programs/incoming-class-profile', 'test-required', '펜실베이니아주 필라델피아 도심 서쪽 University City 지구에 캠퍼스를 둔 아이비리그 사립대학이다.', '인구 약 160만의 대도시 필라델피아 시내에 있는 도심형 캠퍼스로, 뉴욕과 워싱턴 D.C. 사이에 위치하며 사계절이 뚜렷한 기후다.');
insert into schools (id, name, name_ko, usnews_rank, tier, sat_mid50_low, sat_mid50_high, gpa_note, intl_accept_rate, need_blind_intl, demonstrated_interest, direct_admit_majors, what_they_value, source_url, test_policy, intro_ko, location_note) values (11, 'California Institute of Technology (Caltech)', '캘리포니아 공과대학교(칼텍)', 11, 1, null, null, '석차 제출자 기준 신입생 86.4%가 고교 상위 10% (CDS 2024-25 C10)', null, false, false, '{}', 'CDS 2024-25 C7에서 교과 이수 난이도(rigor), 표준화 시험 점수, 에세이, 추천서, 인성/개인 자질을 Very Important로 명시한다. 공식 ''What We Look For'' 페이지는 고급 수학이 요구하는 추상적 사고와 문제 해결 능력을 중시하며, 정해진 ''칼텍형 학생''은 없고 각자의 학교·지역·기회라는 맥락 속에서 지원서를 평가한다고 밝힌다. (출처: admissions.caltech.edu What We Look For + CDS C7)', 'https://www.admissions.caltech.edu/apply/what-we-look-for', 'test-required', '캘리포니아주 패서디나(로스앤젤레스 인근)의 교외 주거지역에 있는 소규모 이공계 중심 사립대학이다.', 'LA 도심에서 북동쪽으로 약 17km 떨어진 중소도시 패서디나에 있으며, 연중 온화하고 건조한 남캘리포니아 기후의 컴팩트한 캠퍼스다.');
insert into schools (id, name, name_ko, usnews_rank, tier, sat_mid50_low, sat_mid50_high, gpa_note, intl_accept_rate, need_blind_intl, demonstrated_interest, direct_admit_majors, what_they_value, source_url, test_policy, intro_ko, location_note) values (12, 'Cornell University', '코넬대학교', 12, 1, 1510, 1560, '석차 제출 신입생(전체의 18.3%) 중 85.6%가 고교 상위 10% (CDS 2024-25 C10)', null, false, false, '{"cs","engineering","business","math_data","natural_sci","social_sci","humanities","arts"}', 'CDS 2024-25 C7에서 ''Very Important''로 공식 표기한 항목은 교과 난이도(rigor), 에세이, 추천서, 교외 활동(extracurricular activities), 재능(talent/ability), 인성(character/personal qualities)입니다. 석차·GPA는 Important, 시험 점수는 Considered입니다. 입학처는 시험 점수를 GPA·교과 난이도·활동·에세이·추천서 등 다른 자료와 함께 맥락 속에서 본다고 공식 명시하며, 8개 칼리지 중 하나에 직접 지원하는 구조라 지원 칼리지별 에세이와 요건이 다릅니다.', 'https://irp.dpb.cornell.edu/wp-content/uploads/2025/07/CDS-2024-2025-v6-print.pdf', 'test-required', '뉴욕주 이타카(Ithaca)의 소도시에 위치하며, 언덕 위에 자리한 넓은 전원형 캠퍼스입니다.', '이타카는 인구 약 3만의 대학 도시로 뉴욕시에서 차로 약 4시간 거리이며, 겨울이 길고 추운 편입니다.');
insert into schools (id, name, name_ko, usnews_rank, tier, sat_mid50_low, sat_mid50_high, gpa_note, intl_accept_rate, need_blind_intl, demonstrated_interest, direct_admit_majors, what_they_value, source_url, test_policy, intro_ko, location_note) values (13, 'Brown University', '브라운대학교', 13, 1, 1470, 1550, '석차 제출 신입생(전체의 29.3%) 중 93%가 고교 상위 10% (CDS 2025-26 C10)', null, true, false, '{}', 'CDS 2025-26 C7에서 ''Very Important''로 공식 표기한 항목은 교과 난이도, 석차, GPA, 표준화 시험 점수, 에세이, 추천서, 재능(talent/ability), 인성입니다. 교외 활동은 Important, 인터뷰와 지원자 관심도는 Not Considered입니다. 입학처는 시험 점수를 ''각 학생이 지원하는 개인적 맥락(individual context)에 근거해'' 평가한다고 공식 명시합니다.', 'https://web.archive.org/web/20260429124047/https://oir.brown.edu/sites/default/files/2020-04/CDS-PDF-2025-2026.pdf', 'test-required', '로드아일랜드주 프로비던스(Providence)의 칼리지 힐 지역에 위치한 도시형 캠퍼스입니다.', '프로비던스는 인구 약 19만의 중소 도시로 보스턴에서 차로 약 1시간 거리에 있습니다.');
insert into schools (id, name, name_ko, usnews_rank, tier, sat_mid50_low, sat_mid50_high, gpa_note, intl_accept_rate, need_blind_intl, demonstrated_interest, direct_admit_majors, what_they_value, source_url, test_policy, intro_ko, location_note) values (14, 'Dartmouth College', '다트머스칼리지', 13, 1, 1440, 1550, '석차 제출 신입생(전체의 44%) 중 96%가 고교 상위 10% (CDS 2025-26 C10)', null, true, true, '{}', 'CDS 2025-26 C7에서 ''Very Important''로 공식 표기한 항목은 교과 난이도, 석차, GPA, 표준화 시험 점수, 에세이, 추천서, 교외 활동, 인성입니다. 5개 대학 중 유일하게 지원자 관심도(Level of applicant''s interest)가 ''Considered''로 공식 표기되어 있습니다. 시험 점수는 최고 섹션 점수 조합(superscore)으로 평가한다고 입학처가 공식 안내합니다.', 'https://www.dartmouth.edu/oir/pdfs/cds_2025-26.pdf', 'test-required', '뉴햄프셔주 하노버(Hanover)의 소도시에 위치한 전원형 캠퍼스입니다.', '하노버는 인구 약 1만의 작은 대학 마을로 자연에 둘러싸여 있으며 겨울이 길고 눈이 많습니다.');
insert into schools (id, name, name_ko, usnews_rank, tier, sat_mid50_low, sat_mid50_high, gpa_note, intl_accept_rate, need_blind_intl, demonstrated_interest, direct_admit_majors, what_they_value, source_url, test_policy, intro_ko, location_note) values (15, 'Columbia University', '컬럼비아대학교', 15, 1, 1510, 1560, '석차 제출 신입생(전체의 25.7%) 중 94%가 고교 상위 10% (CDS 2024-25 C10)', null, false, false, '{"engineering"}', 'CDS 2024-25 C7에서 ''Very Important''로 공식 표기한 항목은 교과 난이도, 석차, GPA, 에세이, 추천서, 교외 활동, 인성입니다. 시험 점수는 Considered, 지원자 관심도는 Not Considered입니다. 입학처는 ''학업 우수성(academic excellence)을 기반으로 지원서 전체를 신중히 검토하는 전인적(holistic) 심사''와 개인의 상황·기회 요인 고려를 공식 명시합니다.', 'https://opir.columbia.edu/sites/opir.columbia.edu/files/content/Common%20Data%20Set/2024-25_Columbia_College_and_Columbia_Engineering_CDS.pdf', 'test-optional', '뉴욕시 맨해튼 모닝사이드 하이츠(Morningside Heights)에 위치한 도심형 캠퍼스입니다.', '미국 최대 도시 뉴욕 맨해튼 안에 있어 대중교통과 도시 인프라 접근성이 높은 환경입니다.');
insert into schools (id, name, name_ko, usnews_rank, tier, sat_mid50_low, sat_mid50_high, gpa_note, intl_accept_rate, need_blind_intl, demonstrated_interest, direct_admit_majors, what_they_value, source_url, test_policy, intro_ko, location_note) values (16, 'University of California, Berkeley', 'UC 버클리(캘리포니아대학교 버클리)', 15, 1, null, null, '2026년 가을 합격자의 고교 GPA 중간 50%는 4.16–4.28(가중 GPA)이며, CDS 2025-26 기준 재학 신입생 평균 고교 GPA는 3.90(4.0 만점)입니다.', 6, null, false, '{"engineering","cs","math_data","business"}', 'UC 공통 종합심사(comprehensive review) 13개 기준으로 평가하며, A-G 교과 GPA, 우등·AP·IB 과목 이수와 성적, 고교 여건 대비 성취, 특별한 재능·성취·리더십, 개인 환경을 고려한 학업 성취를 봅니다. CDS 2025-26 기준 ''매우 중요'' 요소는 교과 난이도·GPA·에세이(PIQ)이며, 특별활동·인성·봉사·직업 경험은 ''Important''입니다. (출처: UC ''How applications are reviewed'' 공식 페이지 및 UC Berkeley CDS 2025-26 C7)', 'https://admission.universityofcalifornia.edu/counselors/preparing-freshman-students/freshman-requirements.html', 'test-free', '캘리포니아주 버클리에 위치한 공립대학으로, 샌프란시스코만 동쪽의 도시형 캠퍼스입니다.', '버클리는 샌프란시스코에서 만 건너편에 있는 인구 약 12만 명의 대학 도시로, 연중 온화한 기후이며 대중교통(BART)으로 샌프란시스코와 연결됩니다.');
insert into schools (id, name, name_ko, usnews_rank, tier, sat_mid50_low, sat_mid50_high, gpa_note, intl_accept_rate, need_blind_intl, demonstrated_interest, direct_admit_majors, what_they_value, source_url, test_policy, intro_ko, location_note) values (17, 'Rice University', '라이스 대학교', 17, 1, 1510, 1560, 'CDS 2025-26 기준 신입생의 90%가 고교 졸업 석차 상위 10% 이내입니다(GPA 분포는 미공개).', null, false, true, '{"arts"}', 'CDS 2025-26 기준 ''매우 중요'' 요소는 교과 난이도·석차·GPA·표준화 시험 점수·에세이·추천서·특별활동·재능·인성으로 폭넓습니다. 지원자의 관심도(Level of applicant''s interest)도 ''Considered''로 반영됩니다. 라이스는 시험 점수를 홀리스틱 리뷰의 여러 요소 중 하나로 본다고 공식적으로 밝히고 있습니다. (출처: Rice CDS 2025-26 C7·C8F, admission.rice.edu)', 'https://ideas.rice.edu/wp-content/uploads/2026/07/CDS_2025-26_WEBSITE.pdf', 'test-optional', '텍사스주 휴스턴의 뮤지엄 디스트릭트 인근에 위치한 사립 연구중심대학으로, 대도시 안의 녹지형 캠퍼스입니다.', '휴스턴은 미국 4위 규모의 대도시로 여름이 덥고 습한 아열대성 기후이며, 캠퍼스는 세계 최대 의료단지인 텍사스 메디컬 센터와 인접해 있습니다.');
insert into schools (id, name, name_ko, usnews_rank, tier, sat_mid50_low, sat_mid50_high, gpa_note, intl_accept_rate, need_blind_intl, demonstrated_interest, direct_admit_majors, what_they_value, source_url, test_policy, intro_ko, location_note) values (18, 'University of California, Los Angeles (UCLA)', 'UCLA(캘리포니아대학교 로스앤젤레스)', 17, 1, null, null, '2026년 가을 합격자의 고교 GPA 중간 50%는 4.20–4.30(가중 GPA 기준)입니다.', 6, null, false, '{"engineering","cs","arts","premed"}', 'UC 공통 종합심사(comprehensive review) 13개 기준으로 평가하며, A-G 교과 GPA, AP·IB 등 심화 과목 이수와 성적, 재학 고교의 여건 대비 성취도, 특별한 재능·수상·리더십 경험, 삶의 환경을 고려한 학업 성취 등을 봅니다. CDS 2025-26 기준 ''매우 중요(Very Important)'' 요소는 교과 난이도(rigor)·GPA·지원 에세이(PIQ)입니다. (출처: UC ''How applications are reviewed'' 공식 페이지 및 UCLA CDS 2025-26 C7)', 'https://admission.universityofcalifornia.edu/counselors/preparing-freshman-students/freshman-requirements.html', 'test-free', '미국 캘리포니아주 로스앤젤레스 웨스트우드(Westwood) 지역에 위치한 대형 공립대학으로, 도심형 캠퍼스입니다.', '로스앤젤레스는 미국에서 두 번째로 큰 도시로 연중 온화한 지중해성 기후이며, 캠퍼스는 태평양 연안에서 약 8km 떨어진 주거·상업 지역에 있습니다.');
insert into schools (id, name, name_ko, usnews_rank, tier, sat_mid50_low, sat_mid50_high, gpa_note, intl_accept_rate, need_blind_intl, demonstrated_interest, direct_admit_majors, what_they_value, source_url, test_policy, intro_ko, location_note) values (19, 'Vanderbilt University', '밴더빌트 대학교', 17, 1, 1510, 1560, 'CDS 2025-2026 기준 신입생 평균 고교 GPA는 3.90(4.0 만점)이고, 91%가 고교 석차 상위 10% 이내입니다.', null, false, false, '{"engineering","arts"}', 'CDS 2025-2026 기준 ''매우 중요'' 요소는 교과 난이도·석차·GPA·에세이·특별활동·인성(character/personal qualities)입니다. 표준화 시험 점수와 재능은 ''Important'', 추천서·인터뷰는 그보다 낮은 비중입니다. (출처: Vanderbilt CDS 2025-2026 C7)', 'https://www.vanderbilt.edu/dsa/common-data-set/', 'test-optional', '테네시주 내슈빌 도심 인근에 위치한 사립 연구중심대학으로, 캠퍼스 전체가 수목원으로 지정된 도시형 캠퍼스입니다.', '내슈빌은 음악 산업의 중심지로 알려진 인구 약 70만 명의 중형 도시이며, 캠퍼스는 다운타운에서 약 2.5km 거리에 있고 사계절이 뚜렷한 기후입니다.');
insert into schools (id, name, name_ko, usnews_rank, tier, sat_mid50_low, sat_mid50_high, gpa_note, intl_accept_rate, need_blind_intl, demonstrated_interest, direct_admit_majors, what_they_value, source_url, test_policy, intro_ko, location_note) values (20, 'Carnegie Mellon University', '카네기멜런대학교', 20, 1, 1500, 1560, '신입생 평균 고교 GPA 3.89이며 43.9%가 GPA 4.0, 82.5%가 고교 상위 10% 이내입니다 (CDS 2025-26 C10-C12).', null, false, false, '{"cs","engineering","business","math_data","natural_sci","social_sci","humanities","arts"}', '최신 CDS(2025-26) C7 기준으로 교육과정의 엄격함(rigor), 석차, GPA, 교외활동(extracurricular), 인성·개인 자질, 봉사활동을 ''Very Important''로 평가합니다. 에세이·추천서·재능·First generation 여부는 ''Important''이며, 표준화 시험 점수는 ''Considered''입니다. 전형 요소의 비중은 단과대(프로그램)별로 다르다고 공식 명시하고 있습니다.', 'https://www.cmu.edu/ira/CDS/pdf/cds_2025_26/cds-2025-c-first-time-first-year-admission.pdf', 'test-required', '펜실베이니아주 피츠버그(Pittsburgh)에 위치한 사립 연구중심 대학으로, 도심(Oakland 지역)에 캠퍼스가 있습니다.', '피츠버그는 미국 북동부의 중간 규모 도시로 사계절이 뚜렷하며, 캠퍼스는 피츠버그대학교 등과 인접한 대학가에 있습니다.');
insert into schools (id, name, name_ko, usnews_rank, tier, sat_mid50_low, sat_mid50_high, gpa_note, intl_accept_rate, need_blind_intl, demonstrated_interest, direct_admit_majors, what_they_value, source_url, test_policy, intro_ko, location_note) values (21, 'University of Michigan--Ann Arbor', '미시간대학교 앤아버', 20, 1, 1370, 1530, '신입생 평균 고교 GPA 3.9이며 93.9%가 GPA 3.75 이상입니다 (CDS 2025-26 C11-C12).', null, false, true, '{"engineering","business","arts"}', 'CDS 2025-26 C7 기준 교육과정의 엄격함(rigor)과 GPA가 ''Very Important''이고, 시험 점수·에세이·추천서·인성·First generation 여부는 ''Important''입니다. 공식 Selection Process 페이지는 단일 기준이 아닌 전체적 검토(holistic review)를 명시하며, 엄격한 커리큘럼에서의 성취와 교실 밖 리더십·수상·봉사를 중요 평가 요소로 제시하고, 레거시(동문 자녀)는 고려하지 않는다고 밝힙니다.', 'https://obp.umich.edu/wp-content/uploads/pubdata/cds/cds_2025-26_umaa.pdf', 'test-optional', '미시간주 앤아버(Ann Arbor)에 위치한 주립 연구중심 대학으로, 대학 중심 중형 도시에 캠퍼스가 있습니다.', '앤아버는 디트로이트에서 서쪽으로 차로 약 45분 거리의 대표적인 대학 도시(college town)로, 겨울이 길고 추운 오대호 인근 기후입니다.');
insert into schools (id, name, name_ko, usnews_rank, tier, sat_mid50_low, sat_mid50_high, gpa_note, intl_accept_rate, need_blind_intl, demonstrated_interest, direct_admit_majors, what_they_value, source_url, test_policy, intro_ko, location_note) values (22, 'University of Notre Dame', '노트르담 대학교', 20, 1, 1460, 1540, 'CDS 2025-2026 기준 신입생의 92%가 고교 졸업 석차 상위 10% 이내입니다(GPA 분포는 미공개).', null, true, false, '{"business"}', '공식 평가 기준 페이지에서 고교 여건 내 가장 도전적인 교과 이수와 성적, ''이끌고 영향을 만드는(leading and making an impact)'' 특별활동, 교과 교사·카운슬러 추천서, 그리고 지원자의 실제 모습을 보여주는 에세이를 강조합니다. CDS 2025-2026 기준 교과 난이도·석차·GPA·에세이·추천서·특별활동·재능·인성·봉사활동이 ''매우 중요''이며 표준화 시험 점수는 ''Important''입니다. (출처: admissions.nd.edu Evaluation Criteria 및 ND CDS 2025-2026 C7)', 'https://iris.nd.edu/institutional-research/common-data-set-cds/common-data-set/', 'test-optional', '인디애나주 사우스벤드 인근 노터데임(Notre Dame)에 위치한 가톨릭 사립대학으로, 교외형 캠퍼스입니다.', '시카고에서 동쪽으로 약 150km 떨어진 인구 약 10만 명의 소도시권에 있으며, 겨울에 춥고 눈이 많은 오대호 인접 기후입니다.');
insert into schools (id, name, name_ko, usnews_rank, tier, sat_mid50_low, sat_mid50_high, gpa_note, intl_accept_rate, need_blind_intl, demonstrated_interest, direct_admit_majors, what_they_value, source_url, test_policy, intro_ko, location_note) values (23, 'Washington University in St. Louis', '세인트루이스 워싱턴대학교', 20, 1, 1500, 1570, '신입생 평균 고교 GPA는 4.19(제출자 90% 기준, 학교 제출 스케일 그대로)이며 86%가 고교 상위 10% 이내입니다 (CDS 2024-25 C10-C12).', null, false, true, '{"engineering","business","arts"}', 'CDS 2024-25 C7 기준 교육과정의 엄격함(rigor), 석차, GPA, 표준화 시험 점수, 에세이, 추천서, 재능(talent/ability), 인성·개인 자질이 모두 ''Very Important''로 표시되어 있습니다. 교외활동·First generation·봉사·직업 경험은 ''Important'', 지원자의 관심도(demonstrated interest)는 ''Considered''입니다. 출처는 WashU 공식 Common Data Set 2024-25 C7입니다.', 'https://washu.edu/app/uploads/2025/06/2024-2025-WashU-CDS.pdf', 'test-optional', '미주리주 세인트루이스(St. Louis) 인근 교외에 위치한 사립 연구중심 대학으로, 주 캠퍼스(Danforth Campus)는 대형 도시공원인 Forest Park와 인접해 있습니다.', '세인트루이스는 미국 중서부의 중간 규모 도시이며, 캠퍼스는 도심이 아닌 시 서쪽 경계의 교외 주거 지역에 있어 상대적으로 조용한 환경입니다.');
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (1, '4년 과목 플랜 짜기 — 수학 트랙부터 확인', '12학년까지 Calculus 도달 경로가 여기서 결정됨 — 학교 수학 시퀀스를 확인하고, 경로가 안 나오면 여름 보강 계획을 지금 세울 것', 9, 'fall', null, null, false, false, 'rigor', false, 10);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (2, 'GPA 루틴 만들기', '9학년 성적도 GPA에 그대로 들어감 — 과제·시험 준비 루틴은 첫 학기에 잡는 게 가장 쉽고, 상승 곡선의 시작점이 됨', 9, 'fall', null, null, false, false, 'rigor', false, 20);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (3, '성격이 다른 활동 2~3개 시도', '지금은 잘하는 것보다 계속하고 싶은 걸 찾는 시기 — 만들기형·사람형·쓰기형처럼 유형을 다르게 골라볼 것', 9, 'fall', null, null, false, false, 'spike', true, 30);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (4, '학교의 국제 인증(WASC·Cognia 등)과 school profile 존재 확인', '성적표의 대외 신뢰도를 좌우하는 정보 — 학교 행정실에 직접 물어보고, 없다면 AP·SAT 등 외부 지표 비중을 높이는 전략으로', 9, 'fall', null, null, false, true, 'story', false, 40);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (5, '영어 노출량 늘리기 (시험 말고 기반)', 'TOEFL은 아직 멀었음 — 지금은 관심 분야의 영어 콘텐츠를 일상으로 소비하는 습관이 나중의 점수를 만듦', 9, 'fall', null, null, true, false, 'testing', false, 50);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (6, '10학년 과목 신청 — Honors 도전 포함', '리거는 학년마다 한 계단씩 올라가는 그림이 이상적 — 감당 가능한 선에서 Honors를 1~2개 넣을 것', 9, 'spring', null, null, false, false, 'rigor', false, 10);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (7, '시도한 활동 거르기 — 계속할 것만 남기기', '전부 유지하면 전부 얕아짐 — "다음 학기에도 하고 싶은가"로 판단해 2개 이내로', 9, 'spring', null, null, false, false, 'spike', true, 20);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (8, '여름 계획 세우기', '9학년 여름은 부담 없는 탐색이 정답 — 무료·자기주도 활동 하나면 충분하고, 비싼 캠프가 필요한 시기가 아님', 9, 'spring', null, null, false, false, 'spike', true, 30);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (9, '첫해 성적 점검 — 약한 과목 보강 계획', 'AO는 추세를 봄 — 9학년에 흔들린 과목은 10학년 상승으로 덮을 수 있으니 지금 원인을 찾을 것', 9, 'spring', null, null, false, false, 'rigor', false, 40);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (10, '관심 분야 탐색 활동 1개 실행', '결과물이 없어도 됨 — "이 분야가 나랑 맞는지" 확인이 이번 여름의 목표', 9, 'summer', null, null, false, false, 'spike', true, 10);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (11, '관심 분야 독서·기록 습관', '읽고 남긴 기록이 나중에 에세이 재료가 됨 — 짧은 감상이라도 남길 것', 9, 'summer', null, null, false, false, 'story', true, 20);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (12, 'PSAT 연습 응시', '점수가 아니라 형식 경험이 목적 — 실전 감각은 한 번의 경험으로 크게 달라짐', 10, 'fall', null, null, false, false, 'testing', false, 10);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (13, '첫 AP/Honors 과목 안착', '어려워진 과목에서 성적을 지키는 게 이번 학기 최우선 — 리거 상승과 GPA 유지를 동시에 잡는 연습', 10, 'fall', null, null, false, false, 'rigor', false, 20);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (14, '활동 몰입 시작 — 넓히는 시기는 끝', '이제부터는 남긴 활동을 깊게 파는 구간 — 새 활동 추가는 기존 것과 연결될 때만', 10, 'fall', null, null, false, false, 'spike', true, 30);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (15, '추천서 후보 교사와 수업 안에서 신뢰 쌓기', '추천서는 벼락치기가 안 됨 — 11학년에 부탁할 교사 후보를 정하고 질문·참여로 기억에 남는 학생이 될 것', 10, 'fall', null, null, false, true, 'story', false, 40);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (16, '11학년 AP 라인업 확정', 'AP는 전년도에 신청함 — 전공 관련 핵심 AP가 포함됐는지, 미개설이면 자습 응시 계획까지 이번 달에 결정', 10, 'spring', null, null, false, false, 'rigor', false, 10);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (17, 'AP 시험 응시 (수강 중이라면)', '첫 AP 점수는 실전 리허설 — 5점이면 좋지만 시험 운영 경험 자체가 11학년 다과목 시즌의 자산', 10, 'spring', null, null, false, false, 'testing', false, 20);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (18, 'SAT 공부 시작 시점 결정', '표준 리듬은 10학년 여름 시작 → 11학년 가을 1차 응시 — 목표 티어가 높을수록 이 리듬을 지킬 것', 10, 'spring', null, null, false, false, 'testing', false, 30);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (19, '여름 심화 활동 확정', '10학년 여름은 스파이크 만들기의 마지노선 — 프로젝트·리서치·봉사 중 하나를 구체적 계획으로', 10, 'spring', null, null, false, false, 'spike', true, 40);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (20, '심화 활동 착수', '참가가 아니라 만들기 — 여름이 끝날 때 "보여줄 수 있는 것"이 하나 남는 걸 목표로', 10, 'summer', null, null, false, false, 'spike', true, 10);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (21, 'SAT 기초 학습 시작', '진단 모의고사로 시작점 확인 → 약점 영역 중심 학습 — 무료 공식 자료(Khan Academy)로 충분한 단계', 10, 'summer', null, null, false, false, 'testing', false, 20);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (22, 'TOEFL 필요 여부 판단', '목표 학교마다 면제 기준이 다름 — 국제학교 재학 연수로 면제되는 학교도 있으니 목표 리스트 기준으로 확인 후 계획', 10, 'summer', null, null, true, false, 'testing', false, 30);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (23, 'PSAT 실전 응시', '11학년 PSAT는 실전 — SAT 직전 리허설이자 현재 위치 확인', 11, 'fall', null, null, false, false, 'testing', false, 10);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (24, 'SAT 1차 응시 등록·응시', '가을 1차 → 봄 재응시가 표준 — 1차를 미루면 재응시 기회가 사라짐, 응시 장소는 미리 확보', 11, 'fall', null, null, false, false, 'testing', false, 20);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (25, 'AP 다과목 관리 루틴 세우기', '11학년은 최대 하중의 해 — 과목별 주간 루틴 없이는 전 과목이 같이 흔들림', 11, 'fall', null, null, false, false, 'rigor', false, 30);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (26, '리더십 포지션 확보 또는 직접 만들기', 'AO는 직함보다 만든 것을 봄 — 기존 클럽 임원이 어려우면 작게라도 직접 만들 것', 11, 'fall', null, null, false, false, 'leadership', true, 40);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (27, '외부 검증 도전 — 대회·투고 마감 확인', '원서에 들어갈 수확의 마지막 해 — 지금 마감 캘린더를 만들어야 봄의 기회를 놓치지 않음', 11, 'fall', null, null, false, false, 'validation', true, 50);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (28, '추천서 교사 2명 내정', '12학년 가을에 부탁하면 늦음 — 지금부터 그 수업에서 추천서에 쓸 재료(질문·프로젝트·성장)를 만들 것', 11, 'fall', null, null, false, true, 'story', false, 60);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (29, 'SAT 재응시·마무리', '봄 안에 끝내는 게 목표 — 여름·가을은 에세이와 원서의 시간', 11, 'spring', null, null, false, false, 'testing', false, 10);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (30, 'AP 시험 시즌 운영', '다과목 시험은 체력전 — 과목별 우선순위를 정하고 전공 관련 과목에 5점을 집중', 11, 'spring', null, null, false, false, 'testing', false, 20);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (31, '대학 리스트 초안 만들기', 'reach/match/safety 균형이 핵심 — 툴의 둘러보기와 내 위치 마커로 각 그룹 3~4개씩', 11, 'spring', null, null, false, false, 'story', false, 30);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (32, 'TOEFL 마무리', 'SAT와 원서가 몰리기 전에 끝낼 것 — 여름 이후로 밀리면 일정이 겹침', 11, 'spring', null, null, true, false, 'testing', false, 40);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (33, '추천서 공식 부탁', '학년이 끝나기 전 부탁이 예의이자 안전 — 교사가 여름에 쓸 시간을 확보해주는 것', 11, 'spring', null, null, false, false, 'story', false, 50);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (34, '원서 메인 에세이 초안 완성', '12학년 가을엔 쓸 시간이 없음 — 여름 초안, 가을 퇴고가 표준 리듬', 11, 'summer', null, null, false, false, 'story', false, 10);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (35, '대표 활동 마무리·정리', '스파이크를 "보여줄 수 있는 형태"로 — 결과물·숫자·기록을 지금 정리해야 활동란이 쉬워짐', 11, 'summer', null, null, false, false, 'spike', true, 20);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (36, '대학 리스트 확정 + ED/EA 전략 결정', 'ED는 합격 시 등록 의무가 있는 카드 — 진짜 1지망과 재정 조건을 함께 고려해 결정', 11, 'summer', null, null, false, false, 'story', false, 30);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (37, '재정 서류 준비 논의 시작', '은행잔고증명 등은 부모님과 시간이 필요한 서류 — need-aware 학교 지원 전략과도 연결되니 여름에 논의 시작', 11, 'summer', null, null, true, false, 'story', false, 40);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (38, 'Common App 계정 생성·활동란 초안', '활동란 10칸은 생각보다 오래 걸림 — 각 활동을 150자로 압축하는 연습을 지금', 11, 'summer', null, null, false, false, 'story', false, 50);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (39, 'ED/EA 원서 제출 — 마감 역산 관리', '마감일이 아니라 발송 완료일 기준으로 역산 — 추천서·성적표는 내가 아니라 남이 보내는 것이므로 여유가 필수', 12, 'fall', null, null, false, false, 'story', false, 10);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (40, '메인 에세이 완성 + 보충 에세이 착수', '보충 에세이가 진짜 분량 — 학교별 문항을 스프레드시트로 정리하면 겹치는 주제를 재활용할 수 있음', 12, 'fall', null, null, false, false, 'story', false, 20);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (41, '성적표·추천서 발송 확인 — 담당자 직접 지정', '전담 카운슬러가 없으면 발송 주체가 불분명해짐 — 누가 언제 보내는지 이름과 날짜로 확정할 것', 12, 'fall', null, null, false, true, 'story', false, 30);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (42, 'CSS Profile·재정증명 제출', '재정지원 서류는 원서와 마감이 다름 — 학교별 요구 서류와 마감을 따로 관리', 12, 'fall', null, null, true, false, 'story', false, 40);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (43, '12학년 성적 유지', '합격 취소 사유 1위가 성적 급락 — 원서 시즌에도 수업은 평가되고 있음', 12, 'fall', null, null, false, false, 'rigor', false, 50);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (44, 'RD 결과 정리·비교표 만들기', '감정이 아니라 조건으로 비교 — 학비·재정지원·전공 조건을 한 표에 놓고 볼 것', 12, 'spring', null, null, false, false, 'story', false, 10);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (45, '재정지원 오퍼 검토·이의신청 확인', '오퍼는 협상 여지가 있는 경우가 있음 — 다른 학교 오퍼가 근거가 되기도 함', 12, 'spring', null, null, true, false, 'story', false, 20);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (46, '최종 선택·디파짓', '등록 의사 마감일 확인 — 복수 디파짓은 원칙 위반이니 하나만', 12, 'spring', null, null, false, false, 'story', false, 30);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (47, 'I-20 신청·비자 인터뷰 준비', '합격 확정 즉시 시작 — 여름엔 인터뷰가 몰려서 늦으면 출국 일정이 위험해짐', 12, 'spring', null, null, true, false, 'story', false, 40);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (48, '웨이트리스트 대응 (해당 시)', '관심 유지 편지(LOCI)는 새로운 업데이트가 있을 때만 효과 — 형식적 편지는 무의미', 12, 'spring', null, null, false, false, 'story', true, 50);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (49, '입학 준비 — 기숙사·오리엔테이션·수강신청', '입학처 이메일이 여름 내내 옴 — 놓치면 불이익이 실제로 있으니 주 1회 메일 점검 루틴', 12, 'summer', null, null, false, false, 'story', false, 10);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (50, '최종 성적표 발송 확인', '발송 주체를 지정하고 도착까지 확인 — 이게 마지막 서류', 12, 'summer', null, null, false, true, 'story', false, 20);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (51, '활동·툴 인수인계', '만든 것이 남으면 그게 legacy — 후배에게 자료·계정·노하우를 넘기고 기록으로 남길 것', 12, 'summer', null, null, false, false, 'leadership', true, 30);
